{
  "project_id": "c28b274ebd644909a5cb",
  "name": "create_blog_posts_table",
  "query": "create table public.blog_posts (
  id uuid primary key default gen_random_uuid(),
  author_id uuid not null references auth.users (id) on delete cascade,
  title text not null,
  slug text not null unique,
  content text not null,
  excerpt text,
  published boolean not null default false,
  published_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public.blog_posts is 'Blog posts authored by users.';

create index blog_posts_author_id_idx on public.blog_posts (author_id);
create index blog_posts_published_idx on public.blog_posts (published, published_at desc);

-- keep updated_at fresh
create or replace function public.set_updated_at()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger blog_posts_set_updated_at
before update on public.blog_posts
for each row
execute function public.set_updated_at();

alter table public.blog_posts enable row level security;

-- Anyone (including anon) can read published posts
create policy "Published posts are viewable by everyone"
on public.blog_posts
for select
to anon, authenticated
using ( published = true );

-- Authors can view their own posts (including drafts)
create policy "Authors can view their own posts"
on public.blog_posts
for select
to authenticated
using ( (select auth.uid()) = author_id );

-- Authors can insert their own posts
create policy "Authors can insert their own posts"
on public.blog_posts
for insert
to authenticated
with check ( (select auth.uid()) = author_id );

-- Authors can update their own posts
create policy "Authors can update their own posts"
on public.blog_posts
for update
to authenticated
using ( (select auth.uid()) = author_id )
with check ( (select auth.uid()) = author_id );

-- Authors can delete their own posts
create policy "Authors can delete their own posts"
on public.blog_posts
for delete
to authenticated
using ( (select auth.uid()) = author_id );

grant select on public.blog_posts to anon;
grant select, insert, update, delete on public.blog_posts to authenticated;
"
}

